import fs from 'node:fs';
import path from 'node:path';

async function topup() {
  const PIXAR_DIR = 'public/reference_repo/pixar';
  const catalogPath = 'public/reference_repo/catalog.json';
  const catalog = JSON.parse(fs.readFileSync(catalogPath, 'utf8'));

  const existingPixar = catalog.filter(c => c.category === 'pixar');
  console.log('Current pixar count:', existingPixar.length);
  const needed = 100 - existingPixar.length;
  console.log('Needed:', needed);

  const res = await fetch('https://api.github.com/repos/orangci/walls/git/trees/master?recursive=1', { headers: { 'User-Agent': 'Node' } });
  const data = await res.json();
  const allOrangci = data.tree.filter(f => !f.path.includes('/') && /\.(jpg|png|webp|jpeg)/i.test(f.path));

  const usedPaths = new Set(existingPixar.map(p => p.sourcePath));
  const available = allOrangci.filter(f => !usedPaths.has(f.path));
  console.log('Available in orangci:', available.length);

  const additional = available.slice(0, needed);
  let currentNum = existingPixar.length + 1;

  for (const item of additional) {
    const num = String(currentNum++).padStart(3, '0');
    const ext = path.extname(item.path).toLowerCase() || '.jpg';
    const filename = 'pixar_' + num + ext;
    const dest = path.join(PIXAR_DIR, filename);
    const url = 'https://raw.githubusercontent.com/orangci/walls/master/' + encodeURIComponent(item.path);

    try {
      const imgRes = await fetch(url);
      const buf = Buffer.from(await imgRes.arrayBuffer());
      if (buf.length > 5000) {
        fs.writeFileSync(dest, buf);
        catalog.push({
          id: 'pixar_' + num,
          title: item.path.replace(/\.[^.]+$/, '').replace(/[-_]+/g, ' ').replace(/\b\w/g, c => c.toUpperCase()),
          category: 'pixar',
          filename,
          path: '/reference_repo/pixar/' + filename,
          style: 'pixar',
          mood: (currentNum % 3 === 0) ? 'pixar_cozy' : (currentNum % 3 === 1) ? 'dreamy' : 'morning',
          tags: ['pixar', '3d', 'cgi', 'render', 'bloom'],
          source: 'GitHub 3D/CGI Render Curations',
        });
      }
    } catch (e) {
      console.error('Error fetching', item.path, e.message);
    }
  }

  fs.writeFileSync(catalogPath, JSON.stringify(catalog, null, 2));
  const finalPixar = catalog.filter(c => c.category === 'pixar').length;
  console.log('Final counts: Lofi=' + catalog.filter(c=>c.category==='lofi').length + ', Anime=' + catalog.filter(c=>c.category==='anime').length + ', Pixar=' + finalPixar);
}
topup().catch(console.error);
